	        schema: [
	            {
	                type: "object",
	                properties: {
	                    max: {
	                        type: "integer",
	                        minimum: 0
	                    },
	                    maxEOF: {
	                        type: "integer",
	                        minimum: 0
	                    },
	                    maxBOF: {
	                        type: "integer",
	                        minimum: 0
	                    }
	                },
	                required: ["max"],
	                additionalProperties: false
	            }
	        ],

