export class DragTracker {
    constructor() {
        this.managedViews = new WeakSet();
        this.positions = new WeakMap();
    }
    trackDrag(view) {
        if (this.managedViews.has(view))
            return;
        this.managedViews.add(view);
        view.onDragged(({ x, y }) => this.positions.set(view, [x, y]));
    }
    hasTrackedPosition(view) {
        return this.positions.has(view);
    }
    moveToTrackedPosition(view) {
        if (!this.hasTrackedPosition(view)) {
            throw new Error("getTrackedPosition: view does not have tracked position");
        }
        const [x, y] = this.positions.get(view);
        view.x(x);
        view.y(y);
    }
}
